    for application in Application.objects.select_related("person", "person2").order_by(
        "submitted_on", "id"
    ):
        for slot, person in (("person1", application.person), ("person2", application.person2)):
            if person is None:
                continue
            for name in PERSON_TO_APPLICATION_FIELDS:
                setattr(person, name, getattr(application, f"{slot}_{name}"))
            person.save()


